def arggetter(func, _cache={}):
    """Get a named argument of func from its args and kwargs,
    falling back to default value if it's not passed."""
    if func in _cache:
        return _cache[func]

    original = getattr(func, '__original__', None) or unwrap(func)
    sig = inspect.signature(original)

    def getter(name, args, kwargs):
        try:
            bound = sig.bind(*args, **kwargs)
        except TypeError:
            bound = sig.bind_partial(*args, **kwargs)
        bound.apply_defaults()
        arguments = bound.arguments
        if name in arguments:
            return arguments[name]

        param = sig.parameters.get(name)
        if param is None:
            raise TypeError("'%s' is not a parameter of %s" % (name, func.__name__))
        if param.kind is param.VAR_POSITIONAL:
            return ()
        if param.kind is param.VAR_KEYWORD:
            return {}
        raise TypeError("'%s' argument of %s is missing" % (name, func.__name__))

    _cache[func] = getter
    return getter

